    "page.connType.mirror-opposite.btn.totem-animals-calculator": "टोटेम जानवर कैलकुलेटर",
    "page.connType.values-trine.section-label.connection-type": "Connection Type",
    "page.connType.values-trine.h1.values-trine": "मूल्य ट्राइन",
    "page.connType.values-trine.p.shared-value-both-animals-belong-to": "Shared value — both animals belong to the same मूल्य त्रिभुज, so you often speak the same language when it comes to life's priorities.",
    "page.connType.values-trine.p.totem-connections": "<a href=\"connections.html?v=20260807\">← Totem Connections</a>",
    "page.connType.values-trine.p.shared-value-both-animals-belong-to.2": "Shared value — both animals belong to the same मूल्य त्रिभुज: Power & Prestige, Security & Stability, Inspiration & Idealism, or Peace & Harmony. These connections are people who speak the same language as you, values-wise. They have similar priorities when it comes to how to go about dealing with life — whether that be the pursuit of power and craftsmanship in a trade, or the pursuit of peace and an easy-going lifestyle. These are people you don't have to explain yourself to very often, because they're already on the same page as you, so it can be great for any type of relationship: business or pleasure, family or friendship. Cool runnings :)",
    "page.connType.values-trine.h3.other-connection-types": "Other connection types",
    "page.connType.values-trine.li.rainbow": "<a href=\"connection-rainbow.html?v=20260807\">इंद्रधनुष</a>",
